import{_ as B,H as e,f as t,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"第四十二封信-有意为之的偶然（创造画面）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第四十二封信-有意为之的偶然（创造画面）.md","filePath":"去无方向的信/第四十二封信-有意为之的偶然（创造画面）.md","lastUpdated":1795542896000}'),A={name:"去无方向的信/第四十二封信-有意为之的偶然（创造画面）.md"};function a(n,E,s,p,r,o){return e(),t("div",null,[...E[0]||(E[0]=[i('<h1 id="第四十二封信-有意为之的偶然-创造画面" tabindex="-1">第四十二封信-有意为之的偶然（创造画面） <a class="header-anchor" href="#第四十二封信-有意为之的偶然-创造画面" aria-label="Permalink to &quot;第四十二封信-有意为之的偶然（创造画面）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/2.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>上次我给“轻松拍照”定了性，我说你不可能轻松拍照。只要你拍照片儿的时候脑子里闪过任何有关如何呈现这张照片儿的念头，比如场景有没有拍全、合照人员的站位、猫猫狗狗的体态、自家宝宝的神态，那你就不是轻松拍照；只要你在一个场景拍了多于一张照片儿，发照片儿的时候多少要挑一下，那你就不是轻松拍照；只要你拍完照片儿以后会套滤镜、会调色、会修脸，那你就不是轻松拍照。</p><p>除非你是 Vivian Maier 或 Garry Winogrand 那样的人，就上街随便拍，跟胶卷儿不要钱似的，然后根本不看自己拍了什么，第二天继续上街……但我得说明，即便他们不看自己拍的照片儿，他们也不是瞎拍。</p><p>比如咱们看看 Vivian Maier 的 Contact Sheets（底片小样）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/3.png" alt=""></a></p><p>Contact Sheets 就等于是现在的“原图直出无后期”：露天大太阳、庇荫下、半室内、室内、顺光、逆光，场景多变，但基本没有曝光失误，而且，远景建筑、中景人群、近景肖像，距离多变，但完全没有对焦失误……要知道她用的设备可是一台 Rolleiflex 的双反相机，你可以查查，或者有机会自己摸一摸这样的相机，能用这台相机拍出这样的画面是很难的，这是啥基本功！</p><p>所以，我也不认为 Vivian Maier 和 Garry Winogrand 他们是完全的轻松拍照，或者这么说，他们绝不是自始至终的轻松。这个道理基本相当于，如果你想有一天财富自由，可以在家躺平到死，至少现在得努努力吧。</p><p>扯远了，这不是这封信要聊的东西，哈！</p><p>说回来，这个专栏，从开始到现在，虽然贴过很多很多照片儿，但他们基本都是同一种照片儿，我们可以不严谨地管这些照片儿叫“纪实摄影”，这是普通人最常能接触到的领域，也是普通人最可以理解的画面，非常有共鸣，所以，他们很容易变成名作。</p><p>但即便他们是名作，他们也卖不上价儿，布列松的水上小飞人才能卖两万刀，那是什么重量级、且有历史意义、还有收藏价值的一张照片儿啊，才两万刀，为什么？因为无论这些画面有多好看多重要，他们也还是没能逃出日常的范畴，没有显而易见地突破我们日常的视觉经验，所以，好像日常再重要，拍得再好，也没那么值得收藏。</p><p>在全民拍照片儿的时代，纪实摄影这个东西就更不值钱了，纪实嘛，现在谁都能纪，掏出手机就能纪，所以在纪实摄影领域，最容易让人产生“这我也能拍”的错觉。但其实，“记录”这件事儿本就是照片儿这个东西的天然属性，根本不值一提，所以正经的纪实摄影的重点从来不在“纪实”，而在“摄影”。</p><p>你会发现我一直在说我们是在“拍照片儿”，但说到某些照片儿的时候我会说这是“摄影作品”，这两种说法的区别就在于，“拍照片儿”就是“纪实”，而“摄影”是“创造画面”。因为如果不是这样的话，我们的街拍就可以是监控视频的截图；在同一个地方拍的照片儿，我们就不会说这张比那张好；我们不需要讨论取景构图和颜色搭配，不需要了解作品背景，也无从讨论个人风格。</p><p>说回到玛格南，他们拍大街、拍战地、拍民主运动现场，他们拍饥荒、拍洪水、拍新冠肆虐下的世界，他们拍渔船上的风浪、拍毒窝里的瘾君子、拍从天而降的飞行器和围绕着它的成千上万只蝴蝶……我们也拍过大街，拍过狂风暴雨，拍过社区核酸检测的帐篷和白花花的防护服，但我们拍的那些照片儿就是拍照片儿而已，不是摄影。</p><p>玛格南用照片儿记录下来的事情很多，但他们最厉害的，不在于他们记录的事儿多，而在于他们基于最常见的情景，贡献了那么多那么精彩的视觉体验。不要觉得战地洪水瘾君子就不是日常，因为这些东西并没有脱离我们的视觉和思想认知，而老前辈们，在这样的前提下，依然给我们带来了视觉上的享受或刺激，或甚至是震撼。</p><p>王福春的《火车上的中国人》，拍了四十年，从绿皮火车拍到和谐号。这个绝对重量级的项目当然有他的历史价值和文献价值，但这两种价值都是这些照片儿拍完很久之后由后世赋予的。</p><p>一旦被赋予了这两种价值，很多人就把这样的东西看成是历史，是文献，是纪实。但请看看这些照片儿，这些照片儿如果已经好成这样了，那么，不需要多年以后的历史文献价值，他们在被拍出来的那一刻，就已经有他们最核心的价值了——摄影。</p><p>什么是摄影来着？创造画面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/4.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%258D%2581%25E4%25BA%258C%25E5%25B0%2581%25E4%25BF%25A1-%25E6%259C%2589%25E6%2584%258F%25E4%25B8%25BA%25E4%25B9%258B%25E7%259A%2584%25E5%2581%25B6%25E7%2584%25B6%25EF%25BC%2588%25E5%2588%259B%25E9%2580%25A0%25E7%2594%25BB%25E9%259D%25A2%25EF%25BC%2589/5.png" alt=""></a></p><ul><li>《火车上的中国人》王福春</li></ul><p>好，现在有个问题，王老师按住一个题材拍四十年，创造了很多很多精彩的画面，抓拍到了很多很多精彩的瞬间，那么这些“抓拍到的瞬间”算不算是妙手偶得？</p><p>所有的相遇都是久别重逢，所有的偶然都是有意为之……咱们下次继续聊这个事儿。</p>',26)])])}const h=B(A,[["render",a]]);export{g as __pageData,h as default};
